async function calculatePlayerLevel(recentGames) {
  if (recentGames.length === 0) {
    return "beginner";
  }
  const wins = recentGames.filter((game) => game.placement === 1).length;
  const winRate = wins / recentGames.length;
  if (winRate > 0.7) {
    return "advanced";
  } else if (winRate > 0.3) {
    return "intermediate";
  } else {
    return "beginner";
  }
}
