// backend/services/gameLifecycle/botGame.ts
function startBotsForGame(io, gameCode, letterGrid, language, timerSeconds) {
  const bots = getGameBots(gameCode);
  if (bots.length === 0) return;
  if (!letterGrid || !Array.isArray(letterGrid) || letterGrid.length === 0) {
    logger_default.error("BOT", `Cannot start bots for game ${gameCode}: letterGrid is invalid`);
    return;
  }
  logger_default.info("BOT", `Starting ${bots.length} bots for game ${gameCode}`);
  const gameStartTime = Date.now();
  for (const bot of bots) {
    startBot(
      bot,
      letterGrid,
      language,
      async (submission) => {
        const { username, word, score, comboLevel } = submission;
        if (!bot || !bot.isActive) return;
        if (!word || typeof word !== "string") {
          logger_default.warn("BOT", `Bot "${username}" submitted invalid word: ${word}`);
          return;
        }
        addPlayerWord2(gameCode, username, word, {
          autoValidated: true,
          score,
          comboBonus: 0,
          comboLevel: comboLevel || 0,
          isBot: true
        });
        trackBotWord2(gameCode, word, username, score);
        updatePlayerScore2(gameCode, username, score, true);
        const leaderboard = getLeaderboard2(gameCode);
        broadcastToRoom(io, getGameRoom(gameCode), "updateLeaderboard", {
          leaderboard
        });
      },
      timerSeconds,
      gameStartTime
    );
  }
}
