async function vocabularyEnrichmentHandler(socket, payload) {
  try {
    const validatedPayload = VocabularyEnrichmentSchema.safeParse(payload);
    if (!validatedPayload.success) {
      const errorMessage = validatedPayload.error.issues.map((issue) => `${issue.path.join(".")}: ${issue.message}`).join(", ");
      socket.emit("error", {
        error: "VALIDATION_ERROR",
        message: errorMessage
      });
      logger_default.warn("VOCAB_ENRICHMENT", `Validation failed: ${errorMessage}`);
      return;
    }
    const { words, language, date } = validatedPayload.data;
    if (words.length === 0) {
      socket.emit("vocabularyEnriched", { enrichedWords: [] });
      return;
    }
    const enrichedWords = await Promise.all(
      words.map((word) => enrichVocabularyWithContext(word, language, date))
    );
    socket.emit("vocabularyEnriched", { enrichedWords });
    logger_default.info(
      "VOCAB_ENRICHMENT",
      `Enriched ${words.length} words for language ${language}`
    );
  } catch (error) {
    const err = error;
    logger_default.error("VOCAB_ENRICHMENT", `Error enriching vocabulary: ${err.message}`);
    socket.emit("error", {
      error: "ENRICHMENT_ERROR",
      message: "Failed to enrich vocabulary"
    });
  }
}
