function categorizeTopic(topic) {
  const lowercaseTopic = topic.toLowerCase();
  if (lowercaseTopic.includes("sport") || lowercaseTopic.includes("game") || lowercaseTopic.includes("championship") || lowercaseTopic.includes("olympics") || lowercaseTopic.includes("world cup")) {
    return "sports";
  }
  if (lowercaseTopic.includes("bitcoin") || lowercaseTopic.includes("crypto") || lowercaseTopic.includes("stock") || lowercaseTopic.includes("market") || lowercaseTopic.includes("economy")) {
    return "finance";
  }
  if (lowercaseTopic.includes("movie") || lowercaseTopic.includes("film") || lowercaseTopic.includes("music") || lowercaseTopic.includes("concert") || lowercaseTopic.includes("awards") || lowercaseTopic.includes("oscars") || lowercaseTopic.includes("grammy")) {
    return "entertainment";
  }
  if (lowercaseTopic.includes("tech") || lowercaseTopic.includes("ai") || lowercaseTopic.includes("smartphone") || lowercaseTopic.includes("software") || lowercaseTopic.includes("app")) {
    return "technology";
  }
  if (lowercaseTopic.includes("weather") || lowercaseTopic.includes("storm") || lowercaseTopic.includes("hurricane") || lowercaseTopic.includes("temperature") || lowercaseTopic.includes("climate")) {
    return "weather";
  }
  if (lowercaseTopic.includes("election") || lowercaseTopic.includes("politics") || lowercaseTopic.includes("vote") || lowercaseTopic.includes("president") || lowercaseTopic.includes("government")) {
    return "politics";
  }
  return "general";
}
