// server/localeRedirect.ts
var SUPPORTED_LOCALES = ["he", "en", "sv", "ja", "es"];
var DEFAULT_LOCALE = "he";
var SOCIAL_CRAWLERS = [
  "whatsapp",
  "facebookexternalhit",
  "facebot",
  "twitterbot",
  "linkedinbot",
  "slackbot",
  "telegrambot",
  "discordbot",
  "pinterest",
  "redditbot",
  "embedly",
  "quora link preview",
  "outbrain",
  "vkshare",
  "w3c_validator"
];
function isSocialCrawler(userAgent) {
  const ua = (userAgent || "").toLowerCase();
  return SOCIAL_CRAWLERS.some((bot) => ua.includes(bot));
}
function determineLocale(req) {
  const cookies = req.headers.cookie;
  const cookieLocale = cookies?.split(";").find((c2) => c2.trim().startsWith("boggle_language="))?.split("=")[1];
  if (cookieLocale && SUPPORTED_LOCALES.includes(cookieLocale)) {
    return cookieLocale;
  }
  const acceptLanguage = req.headers["accept-language"];
  if (acceptLanguage) {
    const browserLang = acceptLanguage.split(",")[0].split("-")[0].toLowerCase();
    if (SUPPORTED_LOCALES.includes(browserLang)) {
      return browserLang;
    }
  }
  return DEFAULT_LOCALE;
}
function handleLocaleRedirect(req, res, parsedUrl) {
  const userAgent = req.headers["user-agent"] || "";
  const locale = determineLocale(req);
  const queryString = parsedUrl.search || "";
  if (isSocialCrawler(userAgent)) {
    console.log(`[Crawler] Social crawler detected -> rewriting to /${locale}${queryString}`);
    parsedUrl.pathname = `/${locale}`;
    req.url = `/${locale}${queryString}`;
    return false;
  }
  console.log(`[Redirect] Root path redirect: ${req.url} -> /${locale}${queryString}`);
  res.writeHead(307, { Location: `/${locale}${queryString}` });
  res.end();
  return true;
}

