router5.get("/community-words", async (req, res) => {
  try {
    const supabase4 = getSupabase10();
    const language = req.query.language || null;
    const status = req.query.status || null;
    const search = req.query.search || null;
    const sortBy = req.query.sortBy || "net_score";
    const sortOrder = req.query.sortOrder === "asc" ? true : false;
    const limit = Math.min(parseInt(req.query.limit) || 100, 500);
    const offset = parseInt(req.query.offset) || 0;
    let query = supabase4.from("word_scores").select("word, language, likes_count, dislikes_count, net_score, is_potentially_valid, first_submitter, last_voted_at, first_voted_at", { count: "exact" });
    if (language) {
      query = query.eq("language", language);
    }
    if (search) {
      query = query.ilike("word", `%${search}%`);
    }
    if (status === "validated") {
      query = query.gte("net_score", 10);
    } else if (status === "pending_review") {
      query = query.gte("net_score", 3).lt("net_score", 10);
    } else if (status === "rejected") {
      query = query.lt("net_score", 0);
    } else if (status === "pending") {
      query = query.gte("net_score", 0).lt("net_score", 3);
    }
    const validSortFields = ["net_score", "likes_count", "dislikes_count", "created_at", "last_voted_at"];
    const sortField = validSortFields.includes(sortBy) ? sortBy : "net_score";
    query = query.order(sortField, { ascending: sortOrder });
    query = query.range(offset, offset + limit - 1);
    const { data, error, count } = await query;
    if (error) {
      throw error;
    }
    const words = (data || []).map((row) => {
      let wordStatus = "pending";
      if (row.net_score >= 10) {
        wordStatus = "validated";
      } else if (row.net_score >= 3) {
        wordStatus = "pending_review";
      } else if (row.net_score < 0) {
        wordStatus = "rejected";
      }
      return {
        ...row,
        status: wordStatus
      };
    });
    const { data: statsData } = await supabase4.from("word_scores").select("net_score").throwOnError();
    const typedStatsData = statsData;
    const stats2 = {
      total: typedStatsData?.length || 0,
      validated: typedStatsData?.filter((w2) => w2.net_score >= 10).length || 0,
      pendingReview: typedStatsData?.filter((w2) => w2.net_score >= 3 && w2.net_score < 10).length || 0,
      rejected: typedStatsData?.filter((w2) => w2.net_score < 0).length || 0,
      pending: typedStatsData?.filter((w2) => w2.net_score >= 0 && w2.net_score < 3).length || 0
    };
    res.json({
      words,
      total: count || 0,
      stats: stats2,
      pagination: {
        limit,
        offset,
        hasMore: (count || 0) > offset + limit
      }
    });
  } catch (error) {
    const err = error;
    logger_default.error("ADMIN_API", `Community words error: ${err.message}`);
    res.status(500).json({ error: "Failed to fetch community words" });
  }
});
