// utils/dailyChallenge/dateUtils.ts
function getPuzzleNumber2(dateString) {
  const date = dateString ? /* @__PURE__ */ new Date(dateString + "T00:00:00Z") : /* @__PURE__ */ new Date();
  const daysSinceEpoch = Math.floor((date.getTime() - DAILY_CHALLENGE_EPOCH.getTime()) / (24 * 60 * 60 * 1e3));
  return daysSinceEpoch + 1;
}

